using System;
using System.Linq;
using System.Net;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using Contoso.Api.Orders;
using Microsoft.Extensions.Logging.Testing;
using Xunit;

namespace Api.Tests;

/// <summary>
/// The orders client against a stub of the orders service that answers each
/// call with the next status it was given. The retry tests run against the
/// stub's real clock, so a Retry-After it sends is waited out for real.
/// </summary>
public class OrdersClientTests
{
    [Fact]
    public async Task ReturnsNullFor404()
    {
        var stub = new OrdersStub(HttpStatusCode.NotFound);
        var client = new OrderClient(stub.Client);
        Assert.Null(await client.GetAsync(7, CancellationToken.None));
    }

    [Fact]
    public async Task GivesUpAfterMaxRetries()
    {
        var stub = new OrdersStub(Enumerable.Repeat(HttpStatusCode.TooManyRequests, 6).ToArray());
        var client = new OrderClient(stub.Client);
        await Assert.ThrowsAsync<HttpRequestException>(() => client.GetAsync(7, CancellationToken.None));
        Assert.Equal(5, stub.Calls);
    }

    [Fact]
    public async Task LogsRetryCount()
    {
        var log = new FakeLogger<OrderClient>();
        var stub = new OrdersStub(HttpStatusCode.TooManyRequests, HttpStatusCode.OK);
        await new OrderClient(stub.Client).GetAsync(7, CancellationToken.None);
        Assert.Contains(log.Collector.GetSnapshot(), entry => entry.Message == "retry 1 of 5");
    }

    [Fact(Timeout = 30_000)]
    public async Task RetriesOn429()
    {
        var stub = new OrdersStub(HttpStatusCode.TooManyRequests, HttpStatusCode.OK)
        {
            RetryAfter = TimeSpan.FromSeconds(29),
        };
        // The stub asks for 29 s and the test allows 30, so the retry must
        // honour Retry-After rather than its own backoff, and nothing after
        // it may wait at all: under load the stub answers 429 again, and a
        // third attempt runs past the timeout.
        var client = new OrderClient(stub.Client);
        Assert.NotNull(await client.GetAsync(7, CancellationToken.None));
        Assert.Equal(2, stub.Calls);
    }
}

